/**
 * Semantic coverage for the Medical Records Q0 shape. The fixture keeps the cases small while retaining the boundaries
 * that matter to the query: missing encounters, an unqualified date, the inclusive date boundary, multiple qualifying
 * encounters, and medication fanout.
 */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeMedicalQ0SemanticTest {

	private static final String MEDICAL = "http://example.com/theme/medical/";
	private static final String PREFIX = "PREFIX med: <" + MEDICAL + ">\n"
			+ "PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";
	private static final String Q0 = PREFIX
			+ "SELECT (COUNT(DISTINCT ?patient) AS ?count) WHERE {\n"
			+ "  ?patient a med:Patient .\n"
			+ "  OPTIONAL {\n"
			+ "    ?patient med:hasEncounter ?enc .\n"
			+ "    ?enc med:recordedOn ?date .\n"
			+ "    BIND(?date AS ?optDate)\n"
			+ "  }\n"
			+ "  FILTER(?optDate >= \"2024-06-01\"^^xsd:date)\n"
			+ "  OPTIONAL { ?patient med:hasMedication ?med . }\n"
			+ "}";
	private static final String Q0_PATIENTS = PREFIX
			+ "SELECT DISTINCT ?patient WHERE {\n"
			+ "  ?patient a med:Patient .\n"
			+ "  OPTIONAL {\n"
			+ "    ?patient med:hasEncounter ?enc .\n"
			+ "    ?enc med:recordedOn ?date .\n"
			+ "    BIND(?date AS ?optDate)\n"
			+ "  }\n"
			+ "  FILTER(?optDate >= \"2024-06-01\"^^xsd:date)\n"
			+ "  OPTIONAL { ?patient med:hasMedication ?med . }\n"
			+ "}";
	private static final String Q0_NESTED_ALIAS = PREFIX
			+ "SELECT (COUNT(DISTINCT ?patient) AS ?count) WHERE {\n"
			+ "  ?patient a med:Patient .\n"
			+ "  OPTIONAL {\n"
			+ "    ?patient med:hasEncounter ?enc .\n"
			+ "    OPTIONAL {\n"
			+ "      ?enc med:recordedOn ?date .\n"
			+ "      BIND(?date AS ?dateAlias)\n"
			+ "      BIND(?dateAlias AS ?optDate)\n"
			+ "    }\n"
			+ "  }\n"
			+ "  FILTER(?optDate >= \"2024-06-01\"^^xsd:date)\n"
			+ "  OPTIONAL {\n"
			+ "    ?patient med:hasMedication ?med .\n"
			+ "    OPTIONAL { ?med med:code ?medCode . }\n"
			+ "  }\n"
			+ "}";

	private static final List<String> FORCED_AGGREGATE_STRATEGIES = List.of(
			LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_INTERPRETED,
			LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE,
			LmdbNativeAttemptMetrics.PATH_ORDERED_DISTINCT_GROUPS);
	private static final Map<String, String> TEST_PROPERTIES = Map.ofEntries(
			Map.entry("rdf4j.lmdb.nativeQueryEngine.enabled", "true"),
			Map.entry("rdf4j.lmdb.janinoCodegen.enabled", "true"),
			Map.entry("rdf4j.lmdb.janinoCodegen.synchronous", "true"),
			Map.entry("rdf4j.lmdb.janinoCodegen.thresholdRows", "0"),
			Map.entry("rdf4j.lmdb.kernelInterpreter.enabled", "true"));

	@TempDir
	File dataDir;

	private final Map<String, String> previousProperties = new LinkedHashMap<>();
	private SailRepository lmdbRepository;
	private SailRepository memoryRepository;

	@BeforeEach
	void setUp() {
		for (String property : TEST_PROPERTIES.keySet()) {
			previousProperties.put(property, System.getProperty(property));
			System.setProperty(property, TEST_PROPERTIES.get(property));
		}

		lmdbRepository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		memoryRepository = new SailRepository(new MemoryStore());
		populate(lmdbRepository);
		populate(memoryRepository);
	}

	@AfterEach
	void tearDown() {
		try {
			if (lmdbRepository != null) {
				lmdbRepository.shutDown();
			}
		} finally {
			try {
				if (memoryRepository != null) {
					memoryRepository.shutDown();
				}
			} finally {
				for (Map.Entry<String, String> entry : previousProperties.entrySet()) {
					if (entry.getValue() == null) {
						System.clearProperty(entry.getKey());
					} else {
						System.setProperty(entry.getKey(), entry.getValue());
					}
				}
				previousProperties.clear();
			}
		}
	}

	@Test
	void q0CountsInclusiveBoundaryPatientsOnceAcrossAggregateRoutes() {
		assertThat(memoryCount(Q0)).as("the MemoryStore oracle count").isEqualTo(3L);
		assertThat(lmdbCount(Q0, null)).as("automatic LMDB execution").isEqualTo(3L);
		for (String strategy : FORCED_AGGREGATE_STRATEGIES) {
			assertThat(lmdbCount(Q0, strategy)).as("forced LMDB execution: %s", strategy).isEqualTo(3L);
		}

		assertThat(lmdbPatients(Q0_PATIENTS, null)).containsExactly(
				MEDICAL + "patient/after",
				MEDICAL + "patient/equal",
				MEDICAL + "patient/multi");
	}

	@Test
	void nestedOptionalAliasChainMatchesMemoryStoreOracle() {
		assertThat(memoryCount(Q0_NESTED_ALIAS)).as("the MemoryStore oracle count").isEqualTo(3L);
		assertThat(lmdbCount(Q0_NESTED_ALIAS, null))
				.as("automatic LMDB execution with nested OPTIONAL and alias scope")
				.isEqualTo(3L);
	}

	private long lmdbCount(String query, String forcedStrategy) {
		try (SailRepositoryConnection connection = lmdbRepository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
			if (forcedStrategy != null) {
				prepared.setForcedLmdbExecutionStrategy(forcedStrategy);
			}
			return count(prepared);
		}
	}

	private List<String> lmdbPatients(String query, String forcedStrategy) {
		try (SailRepositoryConnection connection = lmdbRepository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
			if (forcedStrategy != null) {
				prepared.setForcedLmdbExecutionStrategy(forcedStrategy);
			}
			return patients(prepared);
		}
	}

	private long memoryCount(String query) {
		try (SailRepositoryConnection connection = memoryRepository.getConnection()) {
			return count(connection.prepareTupleQuery(QueryLanguage.SPARQL, query));
		}
	}

	private static long count(TupleQuery query) {
		try (TupleQueryResult result = query.evaluate()) {
			List<BindingSet> rows = QueryResults.asList(result);
			assertThat(rows).hasSize(1);
			assertThat(rows.get(0).getValue("count")).isInstanceOf(Literal.class);
			return ((Literal) rows.get(0).getValue("count")).longValue();
		}
	}

	private static List<String> patients(TupleQuery query) {
		try (TupleQueryResult result = query.evaluate()) {
			return QueryResults.asList(result)
					.stream()
					.map(row -> row.getValue("patient").stringValue())
					.sorted()
					.toList();
		}
	}

	private static void populate(SailRepository repository) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI patientType = medical(vf, "Patient");
			IRI hasEncounter = medical(vf, "hasEncounter");
			IRI recordedOn = medical(vf, "recordedOn");
			IRI hasMedication = medical(vf, "hasMedication");
			IRI code = medical(vf, "code");

			connection.begin();
			addPatient(connection, vf, patientType, "missing");
			addPatient(connection, vf, patientType, "before");
			addEncounter(connection, vf, hasEncounter, recordedOn, "before", "before", "2024-05-31");
			addPatient(connection, vf, patientType, "equal");
			addEncounter(connection, vf, hasEncounter, recordedOn, "equal", "equal", "2024-06-01");
			addPatient(connection, vf, patientType, "after");
			addEncounter(connection, vf, hasEncounter, recordedOn, "after", "after", "2024-06-02");
			addPatient(connection, vf, patientType, "multi");
			addEncounter(connection, vf, hasEncounter, recordedOn, "multi", "multi-before", "2024-05-31");
			addEncounter(connection, vf, hasEncounter, recordedOn, "multi", "multi-1", "2024-06-01");
			addEncounter(connection, vf, hasEncounter, recordedOn, "multi", "multi-2", "2024-06-03");
			addPatient(connection, vf, patientType, "noDate");
			addEncounter(connection, vf, hasEncounter, recordedOn, "noDate", "noDate", null);

			addMedication(connection, vf, hasMedication, code, "missing", "missing-med", "MISSING");
			addMedication(connection, vf, hasMedication, code, "after", "after-med-1", "AFTER-1");
			addMedication(connection, vf, hasMedication, code, "after", "after-med-2", "AFTER-2");
			addMedication(connection, vf, hasMedication, code, "multi", "multi-med-1", "MULTI-1");
			addMedication(connection, vf, hasMedication, code, "multi", "multi-med-2", "MULTI-2");
			addMedication(connection, vf, hasMedication, code, "multi", "multi-med-3", "MULTI-3");
			addMedication(connection, vf, hasMedication, code, "noDate", "noDate-med", "NO-DATE");
			connection.commit();
		}
	}

	private static void addPatient(SailRepositoryConnection connection, ValueFactory vf, IRI patientType,
			String patientId) {
		connection.add(patient(vf, patientId), RDF.TYPE, patientType);
	}

	private static void addEncounter(SailRepositoryConnection connection, ValueFactory vf, IRI hasEncounter,
			IRI recordedOn, String patientId, String encounterId, String date) {
		IRI encounter = encounter(vf, encounterId);
		connection.add(patient(vf, patientId), hasEncounter, encounter);
		if (date != null) {
			connection.add(encounter, recordedOn, vf.createLiteral(date, XSD.DATE));
		}
	}

	private static void addMedication(SailRepositoryConnection connection, ValueFactory vf, IRI hasMedication, IRI code,
			String patientId, String medicationId, String medicationCode) {
		IRI medication = medication(vf, medicationId);
		connection.add(patient(vf, patientId), hasMedication, medication);
		connection.add(medication, code, vf.createLiteral(medicationCode));
	}

	private static IRI medical(ValueFactory vf, String localName) {
		return vf.createIRI(MEDICAL, localName);
	}

	private static IRI patient(ValueFactory vf, String id) {
		return vf.createIRI(MEDICAL, "patient/" + id);
	}

	private static IRI encounter(ValueFactory vf, String id) {
		return vf.createIRI(MEDICAL, "encounter/" + id);
	}

	private static IRI medication(ValueFactory vf, String id) {
		return vf.createIRI(MEDICAL, "medication/" + id);
	}
}
